-- ts-ai-consultant 1.0.0 – konverzace, spotřeba, rozpočet, limity, leady (MySQL 8 / MariaDB)
CREATE TABLE IF NOT EXISTS ts_ai_conversations (id VARCHAR(64) NOT NULL PRIMARY KEY, lang VARCHAR(8) NOT NULL, ip_hash VARCHAR(64) NOT NULL, page VARCHAR(300) NOT NULL DEFAULT '', turns INT NOT NULL DEFAULT 0, created_at VARCHAR(19) NOT NULL, updated_at VARCHAR(19) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_ai_messages (id INT AUTO_INCREMENT PRIMARY KEY, conv_id VARCHAR(64) NOT NULL, role VARCHAR(10) NOT NULL, text TEXT NOT NULL, meta VARCHAR(200) NOT NULL DEFAULT '', created_at VARCHAR(19) NOT NULL, INDEX ts_ai_messages_conv (conv_id, id)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_ai_usage (id INT AUTO_INCREMENT PRIMARY KEY, month VARCHAR(7) NOT NULL, conv_id VARCHAR(64), model VARCHAR(60) NOT NULL, in_tokens INT NOT NULL DEFAULT 0, out_tokens INT NOT NULL DEFAULT 0, cache_read INT NOT NULL DEFAULT 0, cache_write INT NOT NULL DEFAULT 0, cost_micro BIGINT NOT NULL DEFAULT 0, outcome VARCHAR(30) NOT NULL, created_at VARCHAR(19) NOT NULL, INDEX ts_ai_usage_month (month)) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_ai_reservations (id INT AUTO_INCREMENT PRIMARY KEY, month VARCHAR(7) NOT NULL, micro BIGINT NOT NULL, created_at VARCHAR(19) NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_ai_rate (bucket VARCHAR(120) NOT NULL PRIMARY KEY, window_start BIGINT NOT NULL, count INT NOT NULL) DEFAULT CHARSET=utf8mb4;
CREATE TABLE IF NOT EXISTS ts_ai_leads (id INT AUTO_INCREMENT PRIMARY KEY, submission_id VARCHAR(64) NOT NULL UNIQUE, conv_id VARCHAR(64), name VARCHAR(120) NOT NULL, email VARCHAR(160) NOT NULL, phone VARCHAR(40), company VARCHAR(160), website VARCHAR(300), message TEXT NOT NULL, transcript TEXT NOT NULL, lang VARCHAR(8) NOT NULL, consent_text VARCHAR(500) NOT NULL, consent_at VARCHAR(19) NOT NULL, sink_status VARCHAR(20) NOT NULL, sink_ref VARCHAR(60), created_at VARCHAR(19) NOT NULL) DEFAULT CHARSET=utf8mb4;
